def qr_data_uri(url):
    """Tiny inline PNG QR (~500 bytes) — zero extra requests, print-and-scan ready."""
    if not HAVE_QR:
        return None
    buf = io.BytesIO()
    qrcode.make(url, box_size=5, border=2).save(buf, format="PNG")
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()

