        f'<input type="date" id="bdate" required min="{SOLAR_FROM}-02-05" max="{SOLAR_TO}-01-05"></label>'
        f'<label>{bi("เวลาเกิด (ไม่ทราบก็ข้ามได้)", "Birth time (skip if unknown)")}'
